/**
 * Типы библиотеки компонентов, общие для сборки списка (`builder/app`) и его
 * показа (`builder/shell`). Лежат в ядре, потому что shell не имеет права
 * импортировать из composition root'а.
 */

/**
 * Почему brick не попал в библиотеку.
 *
 * - `loader-missing` — запись есть в манифесте, но лоадера под её `brickPath` в
 *   сборке нет. Это рассинхрон манифеста и `import.meta.glob`: карта лоадеров
 *   разворачивается на этапе трансформации, поэтому в рантайме такое не чинится
 *   — в dev помогает перезапуск сервера, в проде это дефект сборки.
 * - `import-failed` — лоадер есть, но модуль не загрузился (ошибка в самом
 *   brick-файле или в том, что он импортирует).
 */
export type TSkippedBrickReason = 'loader-missing' | 'import-failed';

/**
 * Brick из манифеста, не попавший в библиотеку. Ошибку не несёт: значение
 * уезжает в Nuxt payload, где переживает сериализацию не всякий `Error`, —
 * исходная причина остаётся в консоли.
 */
export interface ISkippedBrick {
    name: string;
    brickPath: string;
    reason: TSkippedBrickReason;
}
